/**
 * Nano-ID style generator backed by Node.js built-in crypto.
 *
 * We deliberately avoid an external nanoid dependency so this package stays
 * zero-runtime-dependency for ID generation.  The algorithm is equivalent to
 * the official nanoid implementation:
 *   - URL-safe alphabet (A-Z a-z 0-9 _ -)
 *   - `crypto.getRandomValues` / `crypto.randomFillSync` for secure bytes
 *   - Rejection sampling to eliminate modulo bias
 */
import { randomFillSync } from "node:crypto";

const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-";
const ALPHABET_LENGTH = ALPHABET.length; // 64 — a power of 2, so no bias!
const DEFAULT_SIZE = 21;

/**
 * Generate a URL-safe, cryptographically-secure nano-ID.
 * @param {number} [size=21] - Desired character count.
 * @returns {string}
 */
export function generateNanoId(size = DEFAULT_SIZE) {
  if (typeof size !== "number" || size < 1 || !Number.isInteger(size)) {
    throw new TypeError(`nanoid size must be a positive integer, got: ${size}`);
  }

  // Over-request bytes to absorb the rejection-sampling discard budget.
  // With a 64-char alphabet we keep every byte whose value < 192 (3×64),
  // so ~75 % of bytes are accepted on average.  Requesting 1.5× is enough.
  const buf = new Uint8Array(Math.ceil(size * 1.5) + 8);
  let id = "";

  while (id.length < size) {
    randomFillSync(buf);
    for (let i = 0; i < buf.length && id.length < size; i++) {
      // Keep values 0-191 to avoid modulo bias (192 = 3 × 64).
      if (buf[i] < 192) {
        id += ALPHABET[buf[i] % ALPHABET_LENGTH];
      }
    }
  }

  return id;
}
